// Curated help; no remote requests, model responses, or stored questions.
export const ARTICLES=[
 {id:'offline',title:'Prepare GameDay for offline use',tags:'offline airplane internet wifi connection prepare install safari home screen ipad',tour:'prepare',path:'Games → Prepare for offline / Check again',answer:'While online, open Games and choose Prepare for offline (or Check again). Wait for success. On iPad, add GameDay to the Home Screen in Safari, reopen that icon and prepare there too. Test a practice game with Wi-Fi and cellular off: record plays, close and reopen, and confirm saved data. Do this before visiting a gym without internet.'},
 {id:'new-game',title:'Create a game or import CoachIQ preparation',tags:'new create setup set up game start prep preparation download json scouting',tour:'prepare',path:'Games → + New game or Import file',answer:'Create a game manually, or import the CoachIQ game preparation JSON file saved on this device. Preparation can carry the exact team name, rosters, scouting and enabled objectives. Save the game locally, then Resume game. Objectives and player credit are optional.'},
 {id:'teams',title:'Link the correct CoachIQ team',tags:'team link name mismatch varsity jv program season wrong import',tour:'prepare',path:'Games → CoachIQ team link',answer:'Download the team-link JSON from the original CoachIQ Live Game screen and import it in GameDay. Choose the exact linked team when creating a game. For an existing unimported result with the wrong team, open More → Correct team for import; this creates a separate corrected copy. This is manual transfer, not automatic syncing.'},
 {id:'rosters',title:'Where are my players and opponent roster?',tags:'roster players athletes names numbers jersey missing list opponent upload available',tour:'objectives',path:'Game setup → Our roster / Opponent roster; live → Scouting & rosters',answer:'Rosters belong to each saved game. Import a fresh CoachIQ preparation file containing both rosters, or enter lines such as “12, Player Name” in game setup. Players need a jersey number for individual credit. An opponent roster is optional: shooter and turnover prompts still accept a manual number. Updating CoachIQ later does not automatically update an already saved GameDay game.'},
 {id:'tracking',title:'Record a possession with just the tags that matter',tags:'track possession paint touch offensive rebound oreb repeat score outcome end points buttons',tour:'tracking',path:'Live tracker → tags → outcome',answer:'Tap the tags that happened, then the outcome to finish one possession. Tap Paint touch or OREB for each occurrence. A miss or offensive rebound does not by itself end the possession. Outcomes save locally. Auto-switch can move you to the other team automatically. Unknown player credit is allowed.'},
 {id:'tag-settings',title:'Change offense and defense tags',tags:'custom tags customize cut ato set play drive kick offense defense different six settings',tour:'tracking',path:'Tracking settings → Offense & defense tags',answer:'Finish the current possession before editing tags. Select offense or defense, choose up to six tags for that side, add a custom choice if needed, then save both lists. The lists can be different. Previously recorded possessions retain their original tag coverage; an untracked tag is not automatically treated as absent.'},
 {id:'auto-switch',title:'Choose which team has the ball',tags:'auto switch autoswitch offense defense side ball wrong team toggle',tour:'tracking',path:'Live tracker → Offense / Defense / Auto-switch',answer:'Offense means your team has the ball; Defense means the opponent has it. Auto-switch changes sides after a saved possession. Technical shots do not switch sides. To switch manually, finish the current possession or undo its tags first. Adding a recovered possession does not change the active side.'},
 {id:'scorer',title:'Choose who scored or shot a free throw',tags:'scorer prompt who scored player points credit assign made basket shooter',tour:'fouls',path:'Live tracker → Scorer prompt On',answer:'Turn Scorer prompt On to choose a roster player after an uncredited offensive scoring outcome. It also asks for the shooter after each FT make or miss, using the appropriate team roster. The attempt or basket saves first. Skip keeps team scoring but leaves player totals incomplete; Assign missing scorers can repair credit later.'},
 {id:'free-throws',title:'Record free-throw makes, misses and and-ones',tags:'free throw throws ft fts shooting bonus miss made and one andone putback rebound',tour:'fouls',path:'Live tracker → Foul → FTs',answer:'Use Foul → FTs for a normal foul-shot trip. Tap FT made or FT missed once per attempt. With Scorer prompt On, assign each shooter or skip. If the offense rebounds a missed FT, keep the possession open, add OREB and continue. Add a made basket for an and-one or putback using Include a made basket / putback. End possession only when it is over; counted FT and basket points are saved together.'},
 {id:'retained-foul',title:'Record a foul when the offense keeps the ball',tags:'foul foul retains retained keep ball inbound non shooting no free throw',tour:'fouls',path:'Live tracker → Foul → keeps ball',answer:'Use Foul → keeps ball when no free throws are awarded and the offense retains the ball. Continue tagging the same possession after the inbound. The foul itself does not finish a possession. If free throws are awarded instead, use Foul → FTs.'},
 {id:'technical',title:'Record a technical foul without adding a possession',tags:'technical tech dead ball free throw scoreboard technical foul',tour:'fouls',path:'Live tracker → Technical foul',answer:'Choose which team shoots, then tap Technical FT made or missed once per attempt. Scorer prompt can credit the shooter for makes and misses. Technical makes update score and credited player points; they do not create possessions, change PPP or switch the active side. Undo last technical FT removes only that attempt and its linked point.'},
 {id:'turnovers',title:'Choose who lost the ball and who forced it',tags:'turnover turnovers forced force lost ball steal offensive foul charge opponent two steps',tour:'tracking',path:'Live tracker → Turnover prompt On → Turnover / Forced turnover',answer:'On offense, Turnover ends the possession with zero points; an offensive foul is a turnover too. The optional prompt chooses our player who lost it. On defense, Forced turnover can choose our player who forced it, then the opponent who lost it in step 2. Either player can remain unassigned; without a roster, enter a manual jersey.'},
 {id:'defense-credit',title:'Record defensive responsibility and breakdown reasons',tags:'defense defensive responsibility beat dribble no help bad closeout rotation breakdown customize',tour:'tracking',path:'Live tracker → Defense prompt On; Tracking settings → Player & turnover prompts',answer:'After a defensive possession containing a made basket, the optional Defense prompt asks for our player or Team / shared, then one primary breakdown reason. Customize the reason list in Player & turnover prompts. This is your observation, not proof that one athlete caused the score. FT-only defensive possessions do not trigger a breakdown prompt.'},
 {id:'objectives',title:'Add and count game-plan objectives',tags:'objective objectives goal target game plan winning manual count plus cards player',tour:'objectives',path:'Tonight’s game plan → Add / Edit objectives',answer:'Choose what to track, the goal, and the team or player. Player choices use the saved game roster, with a manual-number alternative. Automatic objectives update from recorded plays; manual categories have tap buttons directly on their cards. Do not tap a second time to duplicate an automatic count. Incomplete tracking or scorer credit is flagged instead of confidently grading an individual Points target.'},
 {id:'tag-player',title:'Credit an individual paint touch, rebound or deflection',tags:'tag player individual paint touches rebounds deflections jersey credit next tag',tour:'objectives',path:'Tracking settings → Tag player',answer:'Choose the player before tapping the tag. Paint-touch, rebound and shot jerseys belong to the team with the ball; a deflection jersey belongs to the defensive team. Clear the selection for team events or change it before the next player’s tag. Scorer prompts credit scoring outcomes; they do not retroactively credit other tags.'},
 {id:'missed',title:'I missed a possession or a stretch of play',tags:'missed missing forgotten gap forgot add possession recovery incomplete action',tour:'recovery',path:'Live tracker → Missed something?',answer:'If you know the outcome and its order, choose Add possession and put it in the correct period and timeline position. If you do not know exactly what happened, mark a tracking gap. The current unfinished possession stays intact. A gap guesses no scores or possessions and breaks streaks across the missing stretch. Review the whole stretch before resolving a gap in Possessions.'},
 {id:'missing-credit',title:'Skip left points or FT attempts without a player',tags:'skip skipped unassigned missing scorers incomplete credit points zero player totals repair',tour:'recovery',path:'Incomplete-credit notice → Assign missing scorers',answer:'Skip keeps team points but leaves the play unassigned. The notice shows how many recorded points or FT attempts lack a player. Assign missing scorers lets you repair each basket or FT using a roster or manual number, without changing team score. Individual Points goals stay cautious while credit is missing. Repair an exported locked game in CoachIQ where supported; make these GameDay repairs before final export.'},
 {id:'corrections',title:'Undo or correct something entered incorrectly',tags:'undo edit correction mistake wrong score possession change remove',tour:'recovery',path:'Live → Undo tag / Undo possession; Possessions → Edit possession',answer:'Undo tag removes the latest draft selection. Undo possession voids the latest saved possession and retains its history. Edit possession corrects a saved result or individual events with a reason. More → Correct scoreboard changes score without adding a possession. If you later recover the actual scoring possession, review any earlier score adjustment to avoid counting points twice.'},
 {id:'reports',title:'Understand Fix now and Keep doing',tags:'report timeout quarter halftime fix now keep doing insight analysis ai statistics ppp kill kills stops',tour:'reports',path:'Live → Timeout report or End period',answer:'Live reports show up to two evidence-backed concerns and two positives, with short coaching cues. Extra stats, player totals, objectives and scouting stay collapsed until needed. Headlines use recorded recent possessions; no clear pattern is invented for a small sample. Three consecutive recorded defensive stops earn a kill. Open gaps restart streaks and recent windows. Print / save full report includes the supporting detail.'},
 {id:'backup',title:'Save a backup, move devices, or find a JSON download',tags:'backup save files json downloads laptop transfer ipad device move restore automatic sync',tour:'finish',path:'Live → More → Export backup; Games → Import file',answer:'Games save automatically in this browser, but a downloaded backup is a separate JSON copy. Confirm it appears in Files / Downloads. To move devices, transfer that JSON by your chosen file-sharing method and import it on the other device. No automatic cloud sync is provided. Clearing browser data, private browsing or deleting the app can remove local records; keep a backup before doing those things.'},
 {id:'finish',title:'Finish a game and send it back to CoachIQ',tags:'finish export final result lock import coachiq completed after game postgame',tour:'finish',path:'More → Finish game → Export final result & lock',answer:'Confirm the final score, review corrections and missing credit, then export the locked final result JSON. Transfer the file to the device with CoachIQ and import it there. That is separate from a normal backup. Locked copies remain readable but cannot be edited in GameDay. Importing the identical result again should not create a duplicate.'},
 {id:'updates',title:'Update GameDay without deleting games',tags:'update version refresh check again old cached changes publish github',tour:'prepare',path:'Games → Check again / Prepare for offline',answer:'After the GitHub publishing workflow succeeds, open the existing app online and use Check again / Prepare for offline. Close all GameDay windows and reopen the same app. Check the version on the Games screen. Do not clear website data or reinstall to force an update. Update each CoachIQ Apps Script file named in the release instructions before importing new features.'},
 {id:'drills',title:'Track drills and organize drill history',tags:'drill drills practice folder history template session outcomes progress library',tour:'drills',path:'Games screen → Drills & history',answer:'Create or choose a drill template, choose the folder/team and record the outcomes you want to measure. Drill records and game records are separate local libraries. Use the drill backup/import controls for drill JSON files. Folder and template history help compare recorded sessions; they do not automatically sync to CoachIQ or another device.'},
 {id:'delete',title:'Delete a local game safely',tags:'delete remove erase game local data old games',tour:'finish',path:'Games → saved game → Delete',answer:'Delete removes that game from this browser. It does not remove JSON files in Downloads/Files or a result already imported into CoachIQ. Confirm the matchup before deleting, and keep a backup if you may need the record later. Deletion cannot be undone here.'}
];
const step=(title,text,path,target)=>({title,text,path,target});
export const TOURS=[
 {id:'prepare',title:'Get ready for game day',steps:[step('Bring your setup','Import a CoachIQ preparation file, or create a game. Rosters and objectives are optional.','Games → Import file / + New game','[data-action="import"]'),step('Prepare offline','While online, save the app files and verify local storage. Repeat in your Home Screen app.','Games → Prepare for offline / Check again','[data-action="prepare"]'),step('Test your device','Use a practice game in airplane mode. Close and reopen, then verify plays and the unfinished draft.','Open a saved game → Resume game','[data-action="open"]')]},
 {id:'tracking',title:'Learn the live tracker',steps:[step('Choose the ball side','Offense is us with the ball; Defense is opponent ball. Auto-switch is optional.','Live → Offense / Defense','[data-action="side"]'),step('Tap what mattered','Paint touch and OREB count repeated occurrences. Set different tags for each side in Tracking settings.','Live → tags','[data-action="tag"]'),step('Finish once','Choose points or turnover only when that possession ends. This walkthrough does not record an outcome for you.','Live → outcome buttons','.outcomes'),step('Player prompts are optional','Scorer, defense and turnover prompts can be switched independently. Skip retains the saved result.','Live → prompt switches','[data-action="credit-toggle"]')]},
 {id:'fouls',title:'Fouls, FTs and technicals',steps:[step('Foul with no FTs','Use keeps ball and continue the same possession.','Live → Foul → keeps ball','[data-action="foul-retained"]'),step('Normal free throws','Use Foul → FTs, record each make/miss and finish only when play is over. Scorer prompt asks for each shooter.','Live → Foul → FTs','[data-action="foul-fts"]'),step('Dead-ball technical shots','Choose the shooting team and record attempts. Technical shots leave your current possession and tags intact.','Live → Technical foul','[data-action="technical"]')]},
 {id:'objectives',title:'Objectives and player credit',steps:[step('Choose the game plan','Use team goals or select a roster player by name and number. Add only what matters tonight.','Tonight’s game plan → Add / Edit objectives','[data-action="objectives"]'),step('Count from the cards','Manual objectives have tap buttons. Automatic ones use recorded events; do not count them again.','Tonight’s game plan → objective cards','.game-plan-panel'),step('Credit other tags if needed','Tag player credits later paint/rebound/deflection taps. It is separate from the scorer prompt.','Tracking settings → Tag player','[data-action="tracking-settings"]')]},
 {id:'recovery',title:'Fix missed action and player credit',steps:[step('Missed something?','Add a remembered outcome or mark a gap when unsure. Your active draft is preserved.','Live → Missed something?','[data-action="missed"]'),step('Repair player totals','Unassigned points stay in the team score. Assign missing scorers repairs individual credit without adding score.','Incomplete-credit notice → Assign missing scorers','[data-action="missing-scorers"]'),step('Review saved possessions','Edit results, add missed possessions and review open gaps. Resolve a gap only after the whole stretch is checked.','Live → Possessions','[data-action="review"]')]},
 {id:'reports',title:'Read a timeout in seconds',steps:[step('Open the brief','Fix now and Keep doing show up to two supported messages each. Strong wording needs recorded evidence.','Live → Timeout report','[data-action="report"]'),step('Open details only if needed','Stats, player totals, objectives, scouting and coverage notes are collapsed. Full PDF printing includes them.','Report → More detail if you need it','.huddle-detail'),step('End the period','End period records a period/halftime report and advances tracking. Finish the current possession first.','Live → End period','[data-action="period"]')]},
 {id:'finish',title:'Back up and finish a game',steps:[step('Keep a separate copy','Export backup downloads a JSON file. Confirm it saved in Files / Downloads.','Live → More → Export backup','[data-action="game-more"]'),step('Check before locking','Review missed action and missing scorer credit, then confirm final score.','Live → More → Finish game','[data-action="game-more"]'),step('Transfer the final result','Export final result & lock, move the JSON file to CoachIQ and import it. Devices do not sync automatically.','Finished game → Export final result & lock','[data-action="export-result"]')]},
 {id:'drills',title:'Drills and history',steps:[step('Open the drill workspace','Games and drills use separate local libraries. Return to the Games screen to switch workspace.','Games screen → Drills & history','[data-action="drills"]'),step('Choose your drill','Use a template and a consistent folder/team, then count recorded outcomes.','Drills & history → create / choose a drill',null),step('Keep drill backups too','Drill JSON is separate from game JSON. Use drill export/import when moving devices.','Drills & history → backup / import',null)]}
];
const normalize=text=>String(text||'').toLowerCase().replace(/\bback up\b/g,'backup').replace(/[’']/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const stops=new Set('a an and are as at be can do does for from get have how i in is it me my of on or our please the them there this to was we what when where which who why with you your'.split(' '));
function words(text){return normalize(text).split(' ').filter(w=>w&&!stops.has(w)).map(w=>({ft:'free',fts:'free',athlete:'players',athletes:'players',player:'players',rosters:'roster',scored:'scorer',scoring:'scorer',posessions:'possession',possessions:'possession',turnovers:'turnover',objectives:'objective',rebounds:'rebound',misses:'miss',missed:'miss',skipped:'skip'}[w]||w));}
export function searchHelp(question){const raw=String(question||'').trim().slice(0,500),tokens=[...new Set(words(raw))];if(!tokens.length)return[];return ARTICLES.map(article=>{const title=words(article.title),tags=words(article.tags),body=words(article.answer);let score=tokens.reduce((n,w)=>n+(title.includes(w)?5:tags.includes(w)?3:body.includes(w)?1:0),0);if(/where.*(players|athletes)|roster|missing (players|athletes)/.test(normalize(raw))&&article.id==='rosters')score+=8;if(/backup|move.*device|transfer.*device/.test(normalize(raw))&&article.id==='backup')score+=8;if(/\b(ft|fts|free throw)/.test(normalize(raw))&&article.id==='free-throws')score+=8;if(/technical|tech foul/.test(normalize(raw))&&article.id==='technical')score+=10;if(/missing scorer|skip|unassigned|credit/.test(normalize(raw))&&article.id==='missing-credit')score+=5;if(/offline|airplane|wifi/.test(normalize(raw))&&article.id==='offline')score+=6;const matches=tokens.filter(w=>title.includes(w)||tags.includes(w)||body.includes(w)).length;if(score<8&&matches/tokens.length<0.6)score=0;return{...article,score};}).filter(a=>a.score>=3).sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)).slice(0,3);}
